# cc-P760 (generated by make_shots.py): opens the League shop and asks for shots of the window and its confirm step.
import API

SIG = r"D:/UO/golems/Iron/p760-proof/league-signal.txt"
LOG = r"D:/UO/golems/Iron/p760-proof/league.log"


def note(text):
    with open(LOG, "a") as f:
        f.write(text + "\n")
    API.SysMsg("P760: " + text)


def shot(name):
    with open(SIG, "a") as f:
        f.write("SHOT " + name + "\n")
    API.Pause(2)


API.Pause(4)
note("opening the League shop with: [leagueshop")
API.Msg("[leagueshop")
API.Pause(4)
shot("league-window")
API.ReplyGump(220)
API.Pause(4)
shot("league-confirm")
if True:
    API.ReplyGump(1)
    API.Pause(4)
    shot("league-after-buy")
note("done")
with open(SIG, "a") as f:
    f.write("DONE\n")
